// Generated by AI (UnitTest MCP)
import { readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { describe, expect, it } from "vitest";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "../../..");

const specPath = join(repoRoot, "docs/SPEC-CONSTITUTION.md");
const spec = readFileSync(specPath, "utf8");

/** The §13.1 traceability table, which claims a proof for each acceptance property. */
const acceptanceMap = () => {
  const start = spec.indexOf("### 13.1");
  const end = spec.indexOf("## 14.", start);
  expect(start, "SPEC-CONSTITUTION has no §13.1 section").toBeGreaterThan(-1);
  return spec.slice(start, end === -1 ? spec.length : end);
};

/**
 * Backticked identifiers in the §13.1 table.
 *
 * Deliberately case-insensitive. A lower-case-only class silently fails to
 * match a renamed test such as `..._RENAMED`, so the name is never extracted,
 * never reported missing, and the guard passes while the map points nowhere.
 * That was the first version of this test, and it let exactly that through.
 */
const namedTests = () =>
  [...acceptanceMap().matchAll(/`([A-Za-z_][A-Za-z0-9_]{10,})`/g)].map((m) => m[1]);

const rustSources = (dir, out = []) => {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) rustSources(full, out);
    else if (entry.endsWith(".rs")) out.push(full);
  }
  return out;
};

const definedTests = () => {
  const names = new Set();
  for (const dir of ["crates/lodestar-core/src", "crates/lodestar-core/tests"]) {
    for (const file of rustSources(join(repoRoot, dir))) {
      for (const match of readFileSync(file, "utf8").matchAll(/fn (\w+)\(\)/g)) {
        names.add(match[1]);
      }
    }
  }
  return names;
};

describe("constitution acceptance map", () => {
  /**
   * SPEC-CONSTITUTION §13 lists ten acceptance properties; §13.1 names the test
   * that fails if each stops holding. A named test that no longer exists —
   * renamed, merged, deleted — turns the map into decoration pointing nowhere,
   * and the property silently loses its proof while the document still claims
   * one. That is worse than an unmapped property, because it reads as covered.
   */
  it("names only tests that exist", () => {
    const defined = definedTests();
    const named = namedTests();

    const missing = named.filter((name) => !defined.has(name));

    expect(missing).toEqual([]);
  });

  /** Every acceptance property in §13 must appear as a row in §13.1. */
  it("leaves no acceptance property unproved", () => {
    const properties = spec
      .slice(spec.indexOf("## 13. Acceptance properties"), spec.indexOf("### 13.1"))
      .split(/\r?\n/)
      .filter((line) => line.startsWith("- ")).length;

    const rows = acceptanceMap()
      .split(/\r?\n/)
      .filter(
        (line) => line.startsWith("| ") && !line.startsWith("| Property") && !/^\|\s*-+/.test(line)
      ).length;

    expect(rows).toBe(properties);
  });

  /** Guards the guard: a scrape that matches nothing would pass vacuously. */
  it("still finds the tests it is meant to police", () => {
    expect(namedTests().length).toBeGreaterThan(20);
  });
});
